            new Quote { Id = "https://pl.wikiquote.org/wiki/Mikołaj_Rej", Text = "Mocna to zbroja z poczciwością cnota, ta sławy strzeże a broni kłopota.", Author = "Mikołaj Rej" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Mikołaj_Rej", Text = "Nędznik dopiero się uczyć chce jako ma żyw być, kiedyby się począć uczyć jako ma umrzeć.", Author = "Mikołaj Rej" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Mikołaj_Rej", Text = "Nie mów, co chcesz, abyś nie usłyszał, czego nie chcesz.", Author = "Mikołaj Rej" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Mikołaj_Rej", Text = "Nie ten jest mądry, kto wiele spraw umie, lecz kto złe od dobrego rozeznać rozumie.", Author = "Mikołaj Rej" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Mikołaj_Rej", Text = "Póty się człowiek w pięknej rzeczy kocha, póki piękniejszej nie ujrzy.", Author = "Mikołaj Rej" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Mikołaj_Rej", Text = "Próżno kąpiesz z wierzchu ciało, Jeśli wewnątrz co przywrzało.", Author = "Mikołaj Rej" },
