            new Quote { Id = "https://pl.wikiquote.org/wiki/Mikołaj_Rej", Text = "Wołowi, choćbyś wina nalał, pewnie leda w kałuży będzie wodę wolał.", Author = "Mikołaj Rej" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Mikołaj_Rej", Text = "Zła rada zawżdy temu bywa najszkodliwsza, kto ją wymyśla.", Author = "Mikołaj Rej" },
